insert into public.exercise_catalog (id,data) values
('landing', $catalog${"id":"landing","name":"Aterrizaje técnico desde puntillas","aliases":[],"purpose":"Aprender a absorber el peso y estabilizar antes de introducir saltos.","steps":["Coloca los pies a la anchura de caderas y elévate suavemente sobre las puntas.","Vuelve a apoyar los talones y acompaña el descenso con una pequeña flexión de cadera y rodillas.","Quédate estable dos segundos, rodillas siguiendo los pies, y vuelve a empezar."],"mistake":"Dejar caer el cuerpo rígido o convertir el ejercicio en un salto alto.","learn":"Hazlo sin despegar del suelo. La ilustración es orientativa: no necesitas fase de vuelo.","image":{"src":"/training/boxing-exercises-v2.png","tile":11,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('vertical-jump', $catalog${"id":"vertical-jump","name":"Salto vertical con contramovimiento","aliases":[],"purpose":"Producir impulso rápido desde el suelo. Es preparación de potencia, no práctica de golpeo.","steps":["Coloca los pies a la anchura de caderas y libera el espacio por encima y alrededor.","Haz una flexión corta de cadera y rodillas y salta verticalmente con intención rápida.","Aterriza con ambos pies, flexiona suavemente y estabiliza antes de repetir."],"mistake":"Encadenar saltos sin recolocarte o dejar caer las rodillas hacia dentro.","learn":"Empieza con saltos bajos; termina si pierdes estabilidad o altura.","image":{"src":"/training/boxing-exercises-v2.png","tile":0,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('lateral-bound', $catalog${"id":"lateral-bound","name":"Salto lateral corto con estabilización","aliases":[],"purpose":"Impulsar y frenar lateralmente para desarrollar la capacidad física de cambiar apoyos.","steps":["Apóyate en una pierna, con cadera y rodilla ligeramente flexionadas.","Impúlsate una distancia corta hacia el lado contrario y recibe el peso sobre la otra pierna.","Mantén el aterrizaje estable 1–2 segundos antes de volver. Cuenta las repeticiones por lado."],"mistake":"Buscar distancia máxima, cruzar los pies o aterrizar con la rodilla rígida.","learn":"Si cuesta estabilizar, haz un paso lateral amplio sin saltar.","image":{"src":"/training/boxing-exercises-v2.png","tile":1,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('medicine-rotation', $catalog${"id":"medicine-rotation","name":"Lanzamiento rotacional de balón medicinal","aliases":[],"purpose":"Coordinar apoyos, cadera y tronco en una acción explosiva de rotación.","steps":["Usa un balón ligero apto para lanzar y una pared preparada para impactos. Colócate de lado, con la zona despejada.","Sujeta el balón con ambas manos junto a la cadera; pivota los pies y gira cadera y tronco juntos para lanzarlo hacia la pared.","Deja que el balón caiga y recógelo cuando esté parado. Recolócate para cada repetición y cambia de lado."],"mistake":"Girar solo la zona lumbar, fijar los pies al suelo o intentar atrapar un rebote fuerte.","learn":"Primero ensaya despacio sin balón. Aumenta la velocidad antes que el peso.","image":{"src":"/training/boxing-exercises-v2.png","tile":2,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('shadow-rotation', $catalog${"id":"shadow-rotation","name":"Rotación técnica de cadera en sombra","aliases":[],"purpose":"Practicar la secuencia apoyo–cadera–tronco sin lastre. No sustituye la potencia de un lanzamiento.","steps":["Adopta una guardia cómoda, con rodillas suaves y manos sin pesas.","Ensaya un recto de la mano atrasada coordinando el pivote del pie y la rotación de cadera, sin bloquear el codo.","Recupera la guardia y el equilibrio. Repite con pausa; trabaja ambos lados bajo indicación técnica."],"mistake":"Golpear con mancuernas, sobreextender el codo o girar más de lo que permiten los apoyos.","learn":"La ilustración muestra una secuencia de sombra; pide al entrenador que revise tu guardia y pivote.","image":{"src":"/training/boxing-exercises-v2.png","tile":3,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('split-dumbbell', $catalog${"id":"split-dumbbell","name":"Sentadilla dividida con mancuernas","aliases":[],"purpose":"Construir fuerza unilateral para impulsar y frenar desde una base estable.","steps":["Adelanta un pie y separa ambos a la anchura de caderas; las mancuernas quedan a los lados.","Flexiona las dos rodillas bajando casi vertical, con el talón delantero apoyado y el tronco estable.","Empuja el suelo con el pie delantero para volver. Completa un lado y después el otro."],"mistake":"Colocar los pies en una sola línea, perder el equilibrio o golpear el suelo con la rodilla.","learn":"Aprende sin carga y usa un apoyo ligero si lo necesitas.","image":{"src":"/training/boxing-exercises-v2.png","tile":4,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('incline-push', $catalog${"id":"incline-push","name":"Flexión inclinada con empuje rápido","aliases":["Flexiones con manos elevadas"],"purpose":"Trabajar el empuje rápido con una carga corporal regulable; conserva calidad sin llegar al fallo.","steps":["Apoya ambas manos en un banco firme que no pueda deslizarse; cuerpo alineado desde cabeza a talones.","Baja el pecho hacia el apoyo en unos dos segundos, con codos algo separados del tronco.","Empuja rápido sin despegar las manos. Recupera la posición antes de la siguiente repetición."],"mistake":"Hundir la cadera, encoger los hombros o usar un banco inestable.","learn":"Cuanto más alto el apoyo, menor dificultad. No necesitas palmadas ni vuelo.","image":{"src":"/training/boxing-exercises-v2.png","tile":5,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('dumbbell-row', $catalog${"id":"dumbbell-row","name":"Remo unilateral con apoyo","aliases":["Remo con mancuerna apoyado"],"purpose":"Complementar los empujes con fuerza de espalda y control escapular.","steps":["Apoya una mano en un banco firme, separa los pies e inclina el tronco desde la cadera manteniendo la espalda estable.","Con la otra mano, lleva la mancuerna hacia la cadera, moviendo el codo hacia atrás sin girarte.","Baja de forma controlada hasta estirar el brazo y repite. Cambia de lado."],"mistake":"Tirar con impulso, levantar el hombro hacia la oreja o rotar el tronco.","learn":"Empieza ligero y mantén el mismo recorrido en todas las repeticiones.","image":{"src":"/training/boxing-exercises-v2.png","tile":6,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('dumbbell-hinge', $catalog${"id":"dumbbell-hinge","name":"Peso muerto rumano con mancuernas","aliases":[],"purpose":"Fortalecer cadera y cadena posterior para sostener la producción de fuerza.","steps":["Ponte de pie con mancuernas cerca de los muslos y rodillas ligeramente flexionadas.","Lleva la cadera hacia atrás dejando las mancuernas cerca de las piernas; baja solo mientras puedas mantener la espalda estable.","Empuja el suelo y lleva la cadera hacia delante para quedar erguido, sin arquear al final."],"mistake":"Redondear la espalda, separar la carga o convertirlo en una sentadilla.","learn":"Ensaya primero la bisagra sin peso; la profundidad depende de tu movilidad.","image":{"src":"/training/boxing-exercises-v2.png","tile":7,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('one-arm-floor-press', $catalog${"id":"one-arm-floor-press","name":"Press unilateral de suelo con mancuerna","aliases":[],"purpose":"Desarrollar fuerza de empuje unilateral y resistir la rotación del tronco.","steps":["Túmbate con rodillas flexionadas y pies apoyados. Sujeta una mancuerna con muñeca alineada y el brazo a unos 30–45° del tronco.","Desde el brazo suavemente apoyado en el suelo, empuja hacia arriba sin despegar el hombro ni girar el cuerpo.","Baja despacio hasta tocar suavemente el suelo; no rebotes. Completa un brazo y cambia."],"mistake":"Girar todo el tronco, doblar la muñeca o golpear el codo contra el suelo.","learn":"Usa una carga fácil de colocar y retirar; pide ayuda si no puedes hacerlo con control.","image":{"src":"/training/boxing-exercises-v2.png","tile":8,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('side-plank', $catalog${"id":"side-plank","name":"Plancha lateral","aliases":[],"purpose":"Resistir la inclinación lateral y mantener una base estable para transferir fuerzas.","steps":["Túmbate de lado y coloca el antebrazo bajo el hombro; alinea piernas y tronco.","Eleva la cadera formando una línea entre hombro, cadera y tobillos, sin girarte hacia delante.","Respira durante el tiempo indicado; baja con control y cambia de lado."],"mistake":"Colapsar sobre el hombro, hundir la cadera o aguantar la respiración.","learn":"Apoya las rodillas flexionadas para una variante más sencilla.","image":{"src":"/training/boxing-exercises-v2.png","tile":9,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('run-short', $catalog${"id":"run-short","name":"Intervalos de carrera cortos","aliases":[],"purpose":"Repetir esfuerzos cortos con recuperaciones completas y una mecánica de carrera estable.","steps":["Calienta con el trote, movilidad y aceleraciones suaves indicados. Elige terreno regular y sin tráfico.","Corre durante el tiempo de trabajo a la intensidad prescrita: hombros sueltos, zancada natural y apoyo cercano al cuerpo, sin exagerar la inclinación del dibujo.","Recupera caminando o trotando el tiempo completo. Repite las series y termina con vuelta a la calma."],"mistake":"Salir a máxima velocidad en la primera serie o recortar recuperaciones para terminar antes.","learn":"Si no corres habitualmente, alterna marcha y carrera suave. La imagen muestra movimiento, no un ángulo de inclinación que debas copiar.","image":{"src":"/training/boxing-exercises-v2.png","tile":10,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('run-long', $catalog${"id":"run-long","name":"Intervalos de carrera sostenidos","aliases":[],"purpose":"Acumular trabajo aeróbico exigente pero controlado para sostener esfuerzos y recuperar entre ellos.","steps":["Calienta con el trote, movilidad y aceleraciones suaves indicados. Elige terreno regular y sin tráfico.","Corre durante el tiempo de trabajo a la intensidad prescrita: hombros sueltos, zancada natural y apoyo cercano al cuerpo, sin exagerar la inclinación del dibujo.","Recupera caminando o trotando el tiempo completo. Repite las series y termina con vuelta a la calma."],"mistake":"Salir a máxima velocidad en la primera serie o recortar recuperaciones para terminar antes.","learn":"Si no corres habitualmente, alterna marcha y carrera suave. La imagen muestra movimiento, no un ángulo de inclinación que debas copiar.","image":{"src":"/training/boxing-exercises-v2.png","tile":10,"columns":4,"rows":3},"version":1}$catalog$::jsonb),
('goblet-squat', $catalog${"id":"goblet-squat","name":"Sentadilla goblet","aliases":[],"purpose":"Fortalecer piernas y practicar una sentadilla estable con carga delante.","steps":["Sujeta una mancuerna vertical junto al pecho y coloca los pies a una anchura cómoda, con talones apoyados.","Flexiona cadera y rodillas como si te sentaras entre los pies. Mantén las rodillas en la dirección de los dedos.","Baja hasta donde conserves equilibrio y control; empuja el suelo para volver sin inclinarte bruscamente."],"mistake":"Levantar los talones, colapsar las rodillas hacia dentro o dejar caer el tronco.","learn":"Ensaya sin peso y después usa una carga ligera.","image":{"src":"/training/catalog-a.png","tile":0,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('barbell-hinge', $catalog${"id":"barbell-hinge","name":"Peso muerto rumano","aliases":[],"purpose":"Fortalecer la cadena posterior mediante una bisagra de cadera.","steps":["De pie, sujeta la barra delante de los muslos con brazos largos y rodillas ligeramente flexionadas.","Lleva la cadera atrás manteniendo la barra cerca de las piernas y la espalda estable; no busques tocar el suelo.","Vuelve extendiendo la cadera sin arquear la espalda al final. Mantén el recorrido que puedas controlar."],"mistake":"Redondear la espalda o alejar la barra del cuerpo.","learn":"Aprende la bisagra sin carga antes de usar la barra.","image":{"src":"/training/catalog-a.png","tile":1,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('bench-press', $catalog${"id":"bench-press","name":"Press de banca","aliases":[],"purpose":"Desarrollar fuerza de empuje de pecho, hombros y tríceps.","steps":["Usa un banco y rack estables, topes de seguridad o una persona que supervise. Apoya pies, glúteos y parte alta de la espalda.","Saca la barra con muñecas alineadas y bájala controlando hacia la zona media-baja del pecho, sin rebotes.","Empuja hacia arriba manteniendo los hombros estables y vuelve a colocar la barra en el rack al terminar."],"mistake":"Rebotar en el pecho, perder apoyos o entrenar cerca del fallo sin seguridad.","learn":"Elige una carga fácil de controlar y deja las repeticiones en reserva indicadas.","image":{"src":"/training/catalog-a.png","tile":2,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('floor-press', $catalog${"id":"floor-press","name":"Press de suelo con mancuernas","aliases":[],"purpose":"Entrenar el empuje limitando el descenso con el suelo.","steps":["Túmbate con rodillas flexionadas, pies apoyados y una mancuerna en cada mano.","Con los brazos a unos 30–45° del tronco, empuja las mancuernas arriba sin chocar entre sí ni girar las muñecas.","Baja despacio hasta apoyar suavemente la parte posterior de los brazos. Pausa y repite sin rebotar."],"mistake":"Golpear los codos contra el suelo o doblar las muñecas.","learn":"Usa mancuernas que puedas colocar y retirar con seguridad.","image":{"src":"/training/catalog-a.png","tile":3,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('cable-row', $catalog${"id":"cable-row","name":"Remo en polea","aliases":[],"purpose":"Fortalecer espalda y practicar el control de las escápulas.","steps":["Siéntate frente a la polea baja con pies firmes, rodillas algo flexionadas y tronco erguido. Sujeta el agarre con brazos extendidos.","Lleva los codos hacia atrás y el agarre hacia las costillas bajas, sin echar el tronco hacia atrás.","Devuelve el agarre despacio hasta estirar los brazos manteniendo la espalda estable. Repite sin tirones."],"mistake":"Balancear todo el cuerpo, encoger los hombros o tirar con la zona lumbar.","learn":"Empieza ligero y ajusta el asiento y la distancia a la polea.","image":{"src":"/training/catalog-a.png","tile":4,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('lat-pulldown', $catalog${"id":"lat-pulldown","name":"Jalón al pecho","aliases":[],"purpose":"Trabajar la espalda mediante una tracción vertical.","steps":["Ajusta el apoyo sobre los muslos y toma la barra con un agarre cómodo. Mantén los pies apoyados.","Lleva los codos hacia abajo y la barra hacia la parte alta del pecho, con una ligera inclinación estable del tronco.","Deja subir la barra de forma controlada sin perder el apoyo ni soltar la carga de golpe."],"mistake":"Bajar la barra detrás de la nuca o usar el balanceo para mover demasiado peso.","learn":"Reduce la carga si no puedes mantener el mismo recorrido.","image":{"src":"/training/catalog-a.png","tile":5,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('wide-dumbbell-row', $catalog${"id":"wide-dumbbell-row","name":"Remo con mancuernas, codos abiertos","aliases":[],"purpose":"Trabajar la espalda alta con una tracción de codos moderadamente separados.","steps":["Inclina el tronco desde la cadera con rodillas suaves y una mancuerna en cada mano.","Lleva los codos hacia atrás y algo hacia fuera, manteniendo hombros lejos de las orejas.","Baja las mancuernas lentamente sin redondear la espalda ni cambiar la inclinación del tronco."],"mistake":"Abrir los codos al máximo o dar tirones con la espalda baja.","learn":"Usa cargas ligeras; si el tronco pierde estabilidad, elige remo con apoyo.","image":{"src":"/training/catalog-a.png","tile":6,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('split-bodyweight', $catalog${"id":"split-bodyweight","name":"Sentadilla dividida","aliases":["Sentadilla dividida sin carga"],"purpose":"Aprender a producir fuerza con una pierna adelantada y otra atrasada.","steps":["Separa los pies hacia delante y atrás, conservando anchura lateral y equilibrio.","Flexiona ambas rodillas bajando casi vertical, con el talón delantero apoyado.","Empuja el suelo para volver y completa las repeticiones antes de cambiar de pierna."],"mistake":"Colocar los pies en una sola línea o golpear el suelo con la rodilla atrasada.","learn":"Puedes usar un apoyo para mantener el equilibrio.","image":{"src":"/training/catalog-a.png","tile":7,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('hip-thrust', $catalog${"id":"hip-thrust","name":"Hip thrust","aliases":[],"purpose":"Fortalecer los glúteos mediante extensión de cadera con apoyo de espalda.","steps":["Apoya la parte alta de la espalda en un banco que no se deslice y coloca los pies firmes. Protege la pelvis con un acolchado bajo la barra.","Eleva la cadera hasta alinear aproximadamente hombros, cadera y rodillas, manteniendo costillas controladas.","Baja despacio sin perder la posición del banco ni dejar caer la carga."],"mistake":"Arquear la zona lumbar al final o colocar el banco contra el cuello.","learn":"Aprende primero con el peso corporal.","image":{"src":"/training/catalog-b.png","tile":0,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('glute-bridge', $catalog${"id":"glute-bridge","name":"Puente de glúteos con mancuerna","aliases":["Puente de glúteos"],"purpose":"Trabajar la extensión de cadera desde el suelo.","steps":["Túmbate con rodillas dobladas y pies apoyados; sujeta una mancuerna acolchada sobre la pelvis.","Empuja con los pies y eleva la cadera sin abrir las costillas ni arquear la espalda.","Pausa brevemente y baja con control. Mantén la mancuerna sujeta durante todo el movimiento."],"mistake":"Subir más alto a costa de la espalda o dejar rodar la mancuerna.","learn":"Puedes hacerlo sin carga.","image":{"src":"/training/catalog-b.png","tile":1,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('shoulder-press', $catalog${"id":"shoulder-press","name":"Press con mancuernas sentado","aliases":[],"purpose":"Fortalecer hombros y tríceps en un empuje vertical.","steps":["Siéntate con respaldo estable, pies apoyados y mancuernas cerca de los hombros.","Empuja hacia arriba dentro de un recorrido cómodo sin arquear la espalda ni encoger el cuello.","Baja despacio a la posición inicial manteniendo antebrazos bajo las mancuernas."],"mistake":"Compensar con una gran extensión lumbar o forzar un rango doloroso.","learn":"Usa un agarre neutro si te resulta más cómodo y empieza ligero.","image":{"src":"/training/catalog-b.png","tile":2,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('lateral-raise', $catalog${"id":"lateral-raise","name":"Elevaciones laterales","aliases":[],"purpose":"Dar trabajo específico al hombro con una carga moderada.","steps":["De pie, sujeta mancuernas ligeras con brazos a los lados y codos ligeramente flexionados.","Eleva los brazos hacia los lados y un poco hacia delante, hasta un rango cómodo cercano a los hombros.","Baja controlando, sin balancearte ni dejar caer las mancuernas."],"mistake":"Encoger los hombros o convertir la repetición en un impulso de piernas.","learn":"La técnica importa más que el peso.","image":{"src":"/training/catalog-b.png","tile":3,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('barbell-curl', $catalog${"id":"barbell-curl","name":"Curl de bíceps","aliases":[],"purpose":"Fortalecer los flexores del codo.","steps":["Sujeta una barra ligera con palmas hacia delante, codos junto al tronco y muñecas alineadas.","Flexiona los codos para elevar la barra sin mover el tronco ni adelantar mucho los brazos.","Baja hasta un recorrido cómodo de forma lenta y controlada."],"mistake":"Balancearte hacia atrás o doblar las muñecas para terminar la repetición.","learn":"Puedes usar barra EZ si el agarre recto no resulta cómodo.","image":{"src":"/training/catalog-b.png","tile":4,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('dumbbell-curl', $catalog${"id":"dumbbell-curl","name":"Curl de bíceps con mancuernas","aliases":[],"purpose":"Fortalecer los brazos con carga independiente por lado.","steps":["Sujeta una mancuerna en cada mano, con codos próximos al cuerpo y palmas hacia delante.","Flexiona los codos manteniendo el tronco quieto y los hombros relajados.","Desciende despacio y conserva el mismo recorrido en todas las repeticiones."],"mistake":"Dar impulso con la cadera o levantar los hombros.","learn":"Usa menos peso si tienes que balancearte.","image":{"src":"/training/catalog-b.png","tile":5,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('cable-triceps', $catalog${"id":"cable-triceps","name":"Extensión de tríceps en polea","aliases":[],"purpose":"Trabajar el tríceps mediante extensión del codo.","steps":["Colócate frente a una polea alta con cuerda o barra y codos cerca del tronco.","Extiende los codos llevando el agarre hacia abajo sin mover los hombros hacia delante.","Deja que los antebrazos vuelvan lentamente, manteniendo los codos en su sitio."],"mistake":"Inclinar todo el cuerpo sobre el agarre o transformar el movimiento en un empuje de hombro.","learn":"Ajusta una carga que puedas controlar sin bloquear el codo con violencia.","image":{"src":"/training/catalog-b.png","tile":6,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('overhead-triceps', $catalog${"id":"overhead-triceps","name":"Extensión de tríceps con mancuerna","aliases":[],"purpose":"Entrenar la extensión del codo con los brazos elevados.","steps":["Siéntate estable y sujeta una sola mancuerna con ambas manos por encima de la cabeza.","Flexiona los codos para bajar la mancuerna detrás de la cabeza dentro de un recorrido cómodo.","Extiende los codos para volver sin arquear la espalda ni mover de golpe los brazos."],"mistake":"Forzar los hombros o usar una carga difícil de colocar y retirar.","learn":"Pide ayuda para colocar la carga si es necesario; reduce el recorrido si molesta.","image":{"src":"/training/catalog-b.png","tile":7,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('calf-raise', $catalog${"id":"calf-raise","name":"Elevación de gemelos con mancuernas","aliases":["Elevación de gemelos"],"purpose":"Fortalecer la flexión plantar y controlar el tobillo.","steps":["Colócate de pie sobre suelo nivelado con pies paralelos; usa carga solo si mantienes el equilibrio.","Eleva los talones apoyándote sobre los dedos y la parte delantera del pie. Pausa arriba sin saltar.","Baja los talones de forma controlada hasta el suelo y repite."],"mistake":"Rebotar, girar los tobillos hacia fuera o perder el equilibrio.","learn":"Puedes hacerlo sin mancuernas y con un apoyo ligero.","image":{"src":"/training/catalog-c.png","tile":0,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('machine-leg-curl', $catalog${"id":"machine-leg-curl","name":"Curl femoral en máquina","aliases":[],"purpose":"Fortalecer los isquiosurales mediante flexión de rodilla.","steps":["Ajusta la máquina a tu altura: rodillas alineadas con el eje y rodillo sobre la parte baja de la pantorrilla, no en el tendón de Aquiles.","Flexiona las rodillas llevando los talones hacia atrás sin levantar la pelvis del apoyo.","Extiende las piernas lentamente, manteniendo la carga bajo control."],"mistake":"Arquear la espalda o levantar las caderas para mover más peso.","learn":"La ilustración muestra la variante tumbada; pide al monitor que ajuste tu máquina.","image":{"src":"/training/catalog-c.png","tile":1,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('sliding-leg-curl', $catalog${"id":"sliding-leg-curl","name":"Curl femoral deslizante","aliases":[],"purpose":"Trabajar la parte posterior del muslo con el peso corporal.","steps":["Túmbate con talones sobre deslizadores o toallas en un suelo que permita deslizar; rodillas flexionadas.","Eleva la cadera y desliza los talones hacia fuera hasta donde puedas mantener el control.","Acerca de nuevo los talones doblando las rodillas. Baja la cadera entre repeticiones si necesitas facilitarlo."],"mistake":"Extender las piernas más allá de tu capacidad o arquear la espalda.","learn":"Empieza con recorridos cortos; un puente de glúteos es una regresión más sencilla.","image":{"src":"/training/catalog-c.png","tile":2,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('pallof', $catalog${"id":"pallof","name":"Pallof press en polea","aliases":["Pallof press controlado (no equivale a potencia rotacional)"],"purpose":"Resistir la rotación del tronco frente a una fuerza lateral.","steps":["Coloca la polea a la altura del pecho, sitúate de lado al anclaje y separa los pies.","Sujeta el agarre junto al esternón y extiende ambos brazos rectos hacia delante, resistiendo el tirón lateral.","Vuelve al pecho sin girar el tronco. Completa el lado y cambia la orientación para trabajar el otro."],"mistake":"Girar hacia la polea, aguantar la respiración o elegir una carga que te desplace.","learn":"Empieza ligero. La flecha del dibujo no indica que debas girar: el tronco permanece quieto.","image":{"src":"/training/catalog-c.png","tile":3,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('dead-bug', $catalog${"id":"dead-bug","name":"Dead bug","aliases":[],"purpose":"Coordinar brazos y piernas manteniendo el tronco estable.","steps":["Túmbate boca arriba con brazos hacia el techo y caderas y rodillas flexionadas a 90 grados.","Extiende lentamente un brazo y la pierna contraria sin arquear la zona lumbar.","Vuelve al centro, respira y cambia de lado con el mismo control."],"mistake":"Bajar demasiado la pierna y perder la posición de la espalda.","learn":"Reduce el recorrido o mueve solo las piernas si lo necesitas.","image":{"src":"/training/catalog-c.png","tile":4,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('band-row', $catalog${"id":"band-row","name":"Remo con banda","aliases":[],"purpose":"Entrenar la tracción horizontal con resistencia elástica.","steps":["Fija una banda en buen estado a un anclaje seguro delante de ti y siéntate erguido.","Tira llevando los codos hacia atrás y las manos hacia las costillas, sin balancear el tronco.","Vuelve despacio manteniendo tensión y control del anclaje."],"mistake":"Usar una banda dañada o un anclaje que pueda soltarse.","learn":"Comprueba el material antes de empezar y no apuntes la banda hacia tu cara.","image":{"src":"/training/catalog-c.png","tile":5,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('reverse-lunge', $catalog${"id":"reverse-lunge","name":"Zancada hacia atrás","aliases":[],"purpose":"Trabajar fuerza unilateral y control del paso.","steps":["De pie, da un paso hacia atrás manteniendo anchura entre ambos pies.","Flexiona las rodillas bajando la cadera, sin golpear el suelo con la rodilla posterior.","Empuja con el pie delantero y vuelve a la posición inicial con equilibrio."],"mistake":"Dar un paso demasiado estrecho o impulsarte sin controlar el retorno.","learn":"Empieza sin carga y utiliza apoyo si hace falta.","image":{"src":"/training/catalog-c.png","tile":6,"columns":4,"rows":2},"version":1}$catalog$::jsonb),
('hammer-curl', $catalog${"id":"hammer-curl","name":"Curl martillo","aliases":[],"purpose":"Fortalecer brazos con un agarre neutro.","steps":["Sujeta mancuernas con las palmas enfrentadas y codos junto al tronco.","Flexiona los codos sin girar las muñecas ni mover el cuerpo.","Baja despacio y conserva el agarre neutro durante toda la repetición."],"mistake":"Balancear las mancuernas o adelantar los hombros para ayudar.","learn":"Elige un peso que permita movimiento controlado.","image":{"src":"/training/catalog-c.png","tile":7,"columns":4,"rows":2},"version":1}$catalog$::jsonb)
